        { "name": "is_customer", "type": "string", "enum_values": ["yes", "not_customer", "unclear"], "description": "Whether the person on the line is the intended customer.", "min_confidence": 0.85 }
      ],
      "transitions": [
        { "target_node": "identity_check", "description": "It is the customer", "condition": { "logic": "or", "conditions": [ { "variable": "is_customer", "operator": "equals", "operand": "yes" } ] } },
        { "target_node": "not_customer_closing", "description": "Not the customer", "condition": { "logic": "or", "conditions": [ { "variable": "is_customer", "operator": "equals", "operand": "not_customer" } ] } },
        { "target_node": "unclear_closing", "description": "Identity unclear twice", "condition": { "logic": "or", "conditions": [ { "variable": "is_customer", "operator": "equals", "operand": "unclear" } ] } },
        { "target_node": "greeting", "description": "Ask again if unclear", "condition": { "operator": "always" } }
      ],
      "max_node_turns": 3,
      "max_turn_transition": "unclear_closing"
    },

    "not_customer_closing": {
      "name": "not_customer_closing",
      "node_type": "conversation",
      "task_message": "Politely state you cannot discuss the nature of the call. If asked, say you are from Freya Bank and cannot give more detail for privacy reasons. For relatives, request when the customer can be contacted (today/next weekday 10:00-19:00). If a wrong number, mark 'wrong_number'. If deceased, offer condolences and mark 'deceased'. Ask nothing else. Relatives cannot answer security questions.",
      "extraction_schema": [
        { "name": "not_customer_reason", "type": "string", "enum_values": ["callback", "no_callback", "wrong_number", "deceased"], "description": "Reason this is not the customer", "min_confidence": 0.8 }
      ],
      "transitions": [
        { "target_node": "schedule_callback", "description": "Schedule callback requested", "condition": { "logic": "or", "conditions": [ { "variable": "not_customer_reason", "operator": "equals", "operand": "callback" } ] } },
        { "target_node": "customer_not_reached_final", "description": "Other or no callback: no_callback / wrong_number / deceased", "condition": { "logic": "or", "conditions": [ { "variable": "not_customer_reason", "operator": "equals", "operand": "no_callback" }, { "variable": "not_customer_reason", "operator": "equals", "operand": "wrong_number" }, { "variable": "not_customer_reason", "operator": "equals", "operand": "deceased" } ] } }
      ]
