        { "target_node": "collection_stage", "description": "Both verified", "condition": { "logic": "or", "conditions": [ { "variable": "identity_all_verified", "operator": "equals", "operand": "true" }, { "variable": "identity_all_verified", "operator": "equals", "operand": "True" } ] } },
        { "target_node": "identity_check", "description": "Ask next question/reset as needed.", "condition": { "operator": "always" } }
