  "test_variables": { "customer_id": "c_test", "first_name": "Dana", "last_name": "Reyes", "title": "Mr", "now": "2026-10-14T11:00" },
  "nodes": {
    "greeting": {
      "name": "greeting",
      "node_type": "conversation",
      "on_enter": { "type": "tts", "text": "Hello, this is Freya Bank's digital assistant. This call is recorded. Am I speaking with {{title}} {{last_name}}?" },
      "on_enter_first_entry_only": true,
      "task_message": "Ask if you are speaking with {{title}} {{last_name}}. Only a clear yes, 'that's me', 'speaking', or the full name counts as identity confirmation. Do not reveal why you are calling. If unclear, re-ask once, and after two unclear interactions close as not_reached/unclear, answering one question if asked first.",
      "extraction_schema": [
        { "name": "is_customer", "type": "string", "enum_values": ["yes", "not_customer", "unclear"], "description": "Whether the person on the line is the intended customer.", "min_confidence": 0.85 }
      ],
      "transitions": [
        { "target_node": "identity_check", "description": "It is the customer", "condition": { "logic": "or", "conditions": [ { "variable": "is_customer", "operator": "equals", "operand": "yes" } ] } },
        { "target_node": "not_customer_closing", "description": "Not the customer", "condition": { "logic": "or", "conditions": [ { "variable": "is_customer", "operator": "equals", "operand": "not_customer" } ] } },
        { "target_node": "unclear_closing", "description": "Identity unclear twice", "condition": { "logic": "or", "conditions": [ { "variable": "is_customer", "operator": "equals", "operand": "unclear" } ] } },
        { "target_node": "greeting", "description": "Ask again if unclear", "condition": { "operator": "always" } }
      ],
      "max_node_turns": 3,
      "max_turn_transition": "unclear_closing"
    },

    "not_customer_closing": {
      "name": "not_customer_closing",
      "node_type": "conversation",
      "task_message": "Politely state you cannot discuss the nature of the call. If asked, say you are from Freya Bank and cannot give more detail for privacy reasons. For relatives, request when the customer can be contacted (today/next weekday 10:00-19:00). If a wrong number, mark 'wrong_number'. If deceased, offer condolences and mark 'deceased'. Ask nothing else. Relatives cannot answer security questions.",
      "extraction_schema": [
        { "name": "not_customer_reason", "type": "string", "enum_values": ["callback", "no_callback", "wrong_number", "deceased"], "description": "Reason this is not the customer", "min_confidence": 0.8 }
      ],
      "transitions": [
        { "target_node": "schedule_callback", "description": "Schedule callback requested", "condition": { "logic": "or", "conditions": [ { "variable": "not_customer_reason", "operator": "equals", "operand": "callback" } ] } },
        { "target_node": "customer_not_reached_final", "description": "Other or no callback: no_callback / wrong_number / deceased", "condition": { "logic": "or", "conditions": [ { "variable": "not_customer_reason", "operator": "equals", "operand": "no_callback" }, { "variable": "not_customer_reason", "operator": "equals", "operand": "wrong_number" }, { "variable": "not_customer_reason", "operator": "equals", "operand": "deceased" } ] } }
      ]
    },

    "schedule_callback": {
      "name": "schedule_callback",
      "node_type": "conversation",
      "task_message": "Request a date and time (10:00-19:00, today or next business day, after 'now') for callback. If the time is outside allowed range, ask once for another. If still not within window, mark no_callback.",
      "extraction_schema": [
        { "name": "callback_datetime", "type": "string", "description": "Date and time for callback in YYYY-MM-DD HH:MM", "min_confidence": 0.8 }
      ],
      "tools": [
        {
          "type": "function",
          "config": { "timeoutMs": 10000, "maxRetries": 0 },
          "function": {
            "name": "schedule_callback",
            "handler": "__function__:api_call",
            "description": "Book a callback if asked, according to rules. Only call if inside allowed callback window.",
            "parameters": {
              "type": "object",
              "properties": {
                "url": { "type": "string", "default": "https://freya-bank-mock.freyavoice.workers.dev/v1/schedule_callback" },
                "method": { "type": "string", "default": "POST" },
                "headers": { "type": "object", "properties": { "Content-Type": { "type": "string", "default": "application/json" } } },
                "body": {
                  "type": "object",
                  "properties": {
                    "customer_id": { "type": "string", "default": "{{customer_id}}" },
                    "date": { "type": "string", "default": "{{callback_date}}" },
                    "time": { "type": "string", "default": "{{callback_time}}" }
                  },
                  "required": ["customer_id", "date", "time"]
                }
              }
            }
          },
          "response_mapping": [
            { "path": "data.ok", "variable": "callback_ok" }
          ]
        }
      ],
      "transitions": [
        { "target_node": "customer_not_reached_final", "description": "Callback scheduled", "condition": { "logic": "or", "conditions": [ { "variable": "callback_ok", "operator": "equals", "operand": "true" }, { "variable": "callback_ok", "operator": "equals", "operand": "True" } ] } },
        { "target_node": "customer_not_reached_final", "description": "Callback rejected or failed", "condition": { "operator": "always" } }
      ]
    },

    "customer_not_reached_final": {
      "name": "customer_not_reached_final",
      "node_type": "end_call",
      "on_enter": { "type": "silent" },
      "disable_inactivity_monitor": true,
      "terminal": {
        "type": "function",
        "function": {
          "name": "close_call",
          "handler": "__function__:api_call",
          "parameters": {
            "type": "object",
            "properties": {
              "url": { "type": "string", "default": "https://freya-bank-mock.freyavoice.workers.dev/v1/close_call" },
              "method": { "type": "string", "default": "POST" },
              "headers": { "type": "object", "properties": { "Content-Type": { "type": "string", "default": "application/json" } } },
              "body": {
                "type": "object",
                "properties": {
                  "customer_id": { "type": "string", "default": "{{customer_id}}" },
                  "outcome": { "type": "string", "default": "not_reached" },
                  "reason": { "type": "string", "default": "{{not_customer_reason}}" }
                },
                "required": ["customer_id", "outcome", "reason"]
              }
            }
          }
        }
      }
    },

    "unclear_closing": {
      "name": "unclear_closing",
      "node_type": "end_call",
      "on_enter": { "type": "silent" },
      "disable_inactivity_monitor": true,
      "terminal": {
        "type": "function",
        "function": {
          "name": "close_call",
          "handler": "__function__:api_call",
          "parameters": {
            "type": "object",
            "properties": {
              "url": { "type": "string", "default": "https://freya-bank-mock.freyavoice.workers.dev/v1/close_call" },
              "method": { "type": "string", "default": "POST" },
              "headers": { "type": "object", "properties": { "Content-Type": { "type": "string", "default": "application/json" } } },
              "body": {
                "type": "object",
                "properties": {
                  "customer_id": { "type": "string", "default": "{{customer_id}}" },
                  "outcome": { "type": "string", "default": "not_reached" },
                  "reason": { "type": "string", "default": "unclear" }
                },
                "required": ["customer_id", "outcome", "reason"]
              }
            }
          }
        }
      }
    },

    "identity_check": {
      "name": "identity_check",
      "node_type": "conversation",
      "task_message": "Ask for the customer's date of birth (as day, month, year), then the last four digits of their phone number. For the date, parse the answer as day, month, year by default; handle day_month_swapped if hint received. For each answer, call verify_identity. Three total incorrect attempts closes as not_verified/failed. If the customer will not answer, explain questions protect the account, then close as not_verified/declined after a second refusal or question about the call. After passing both, move on.",
      "tools": [
        {
          "type": "function",
          "config": { "timeoutMs": 12000, "maxRetries": 0 },
          "function": {
            "name": "verify_identity",
            "handler": "__function__:api_call",
            "description": "Check one security answer.",
            "parameters": {
              "type": "object",
              "properties": {
                "url": { "type": "string", "default": "https://freya-bank-mock.freyavoice.workers.dev/v1/verify_identity" },
                "method": { "type": "string", "default": "POST" },
                "headers": { "type": "object", "properties": { "Content-Type": { "type": "string", "default": "application/json" } } },
                "body": {
                  "type": "object",
                  "properties": {
                    "customer_id": { "type": "string", "default": "{{customer_id}}" },
                    "field": { "type": "string", "default": "{{identity_field}}" },
                    "answer": { "type": "string", "default": "{{identity_answer}}" }
                  },
                  "required": ["customer_id", "field", "answer"]
                }
              }
            }
          },
          "response_mapping": [
            { "path": "data.ok", "variable": "identity_ok" },
            { "path": "data.verified", "variable": "identity_verified" },
            { "path": "data.all_verified", "variable": "identity_all_verified" },
            { "path": "data.wrong_answers_left", "variable": "identity_wrong_answers" },
            { "path": "data.hint", "variable": "identity_hint" }
          ]
        }
      ],
      "extraction_schema": [
        { "name": "identity_field", "type": "string", "enum_values": ["date_of_birth", "phone_last4"], "description": "Which security question to answer", "min_confidence": 0.8 },
        { "name": "identity_answer", "type": "string", "description": "The answer to the current security question", "min_confidence": 0.7 }
      ],
      "transitions": [
        { "target_node": "not_verified_failed", "description": "Three wrong answers.", "condition": { "logic": "or", "conditions": [ { "variable": "identity_wrong_answers", "operator": "equals", "operand": "0" } ] } },
        { "target_node": "not_verified_declined", "description": "Declined to answer or asked what is this call about twice", "condition": { "logic": "or", "conditions": [ { "variable": "identity_declined", "operator": "equals", "operand": "true" } ] } },
        { "target_node": "products_stage", "description": "Both verified", "condition": { "logic": "or", "conditions": [ { "variable": "identity_all_verified", "operator": "equals", "operand": "true" }, { "variable": "identity_all_verified", "operator": "equals", "operand": "True" } ] } },
        { "target_node": "identity_check", "description": "Ask next question/reset as needed.", "condition": { "operator": "always" } }
      ]
    },
    "not_verified_failed": {
      "name": "not_verified_failed",
      "node_type": "end_call",
      "on_enter": { "type": "silent" },
      "disable_inactivity_monitor": true,
      "terminal": {
        "type": "function",
        "function": {
          "name": "close_call",
          "handler": "__function__:api_call",
          "parameters": {
            "type": "object",
            "properties": {
              "url": { "type": "string", "default": "https://freya-bank-mock.freyavoice.workers.dev/v1/close_call" },
              "method": { "type": "string", "default": "POST" },
              "headers": { "type": "object", "properties": { "Content-Type": { "type": "string", "default": "application/json" } } },
              "body": {
                "type": "object",
                "properties": {
                  "customer_id": { "type": "string", "default": "{{customer_id}}" },
                  "outcome": { "type": "string", "default": "not_verified" },
                  "reason": { "type": "string", "default": "failed" }
                },
                "required": ["customer_id", "outcome", "reason"]
              }
            }
          }
        }
      }
    },
    "not_verified_declined": {
      "name": "not_verified_declined",
      "node_type": "end_call",
      "on_enter": { "type": "silent" },
      "disable_inactivity_monitor": true,
      "terminal": {
        "type": "function",
        "function": {
          "name": "close_call",
          "handler": "__function__:api_call",
          "parameters": {
            "type": "object",
            "properties": {
              "url": { "type": "string", "default": "https://freya-bank-mock.freyavoice.workers.dev/v1/close_call" },
              "method": { "type": "string", "default": "POST" },
              "headers": { "type": "object", "properties": { "Content-Type": { "type": "string", "default": "application/json" } } },
              "body": {
                "type": "object",
                "properties": {
                  "customer_id": { "type": "string", "default": "{{customer_id}}" },
                  "outcome": { "type": "string", "default": "not_verified" },
                  "reason": { "type": "string", "default": "declined" }
                },
                "required": ["customer_id", "outcome", "reason"]
              }
            }
          }
        }
      }
    },

    "products_stage": {
      "name": "products_stage",
      "node_type": "conversation",
      "task_message": "Call get_account to get late products. For each, state the product, past due, and lateness. Ask if the customer can pay all today. If yes, proceed to promise creation for all if confirmed. If not, go through the products one by one, each following its own deadlines and attempts. Read all promises back together before recording. Use add_note for products not promised. After any promise or note, close with the correct outcome as per policy.",
      "tools": [
        {
          "type": "function",
          "config": { "timeoutMs": 12000, "maxRetries": 2 },
          "function": {
            "name": "get_account",
            "handler": "__function__:api_call",
            "description": "Retrieve late products for the customer.",
            "parameters": {
              "type": "object",
              "properties": {
                "url": { "type": "string", "default": "https://freya-bank-mock.freyavoice.workers.dev/v1/get_account" },
                "method": { "type": "string", "default": "POST" },
                "headers": { "type": "object", "properties": { "Content-Type": { "type": "string", "default": "application/json" } } },
                "body": {
                  "type": "object",
                  "properties": {
                    "customer_id": { "type": "string", "default": "{{customer_id}}" }
                  },
                  "required": ["customer_id"]
                }
              }
            }
          },
          "response_mapping": [
            { "path": "data.products", "variable": "products" }
          ]
        },
        {
          "type": "function",
          "config": { "timeoutMs": 12000, "maxRetries": 0 },
          "function": {
            "name": "create_promise",
            "handler": "__function__:api_call",
            "description": "Record a payment promise for each product with user confirmation.",
            "parameters": {
              "type": "object",
              "properties": {
                "url": { "type": "string", "default": "https://freya-bank-mock.freyavoice.workers.dev/v1/create_promise" },
                "method": { "type": "string", "default": "POST" },
                "headers": { "type": "object", "properties": { "Content-Type": { "type": "string", "default": "application/json" } } },
                "body": {
                  "type": "object",
                  "properties": {
                    "customer_id": { "type": "string", "default": "{{customer_id}}" },
                    "product_id": { "type": "string", "default": "{{promise_product_id}}" },
                    "amount": { "type": "number", "default": "{{promise_amount}}" },
                    "date": { "type": "string", "default": "{{promise_date}}" }
                  },
                  "required": ["customer_id", "product_id", "amount", "date"]
                }
              }
            }
          },
          "response_mapping": [
            { "path": "data.ok", "variable": "promise_ok" },
            { "path": "data.promise_id", "variable": "promise_id" }
          ]
        },
        {
          "type": "function",
          "config": { "timeoutMs": 10000, "maxRetries": 0 },
          "function": {
            "name": "add_note",
            "handler": "__function__:api_call",
            "description": "Record reason if promise not made for product.",
            "parameters": {
              "type": "object",
              "properties": {
                "url": { "type": "string", "default": "https://freya-bank-mock.freyavoice.workers.dev/v1/add_note" },
                "method": { "type": "string", "default": "POST" },
                "headers": { "type": "object", "properties": { "Content-Type": { "type": "string", "default": "application/json" } } },
                "body": {
                  "type": "object",
                  "properties": {
                    "customer_id": { "type": "string", "default": "{{customer_id}}" },
                    "product_id": { "type": "string", "default": "{{noted_product_id}}" },
                    "reason": { "type": "string", "default": "{{note_reason}}" }
                  },
                  "required": ["customer_id", "product_id", "reason"]
                }
              }
            }
          },
          "response_mapping": [
            { "path": "data.ok", "variable": "add_note_ok" }
          ]
        }
      ],
      "extraction_schema": [
        { "name": "promise_amount", "type": "number", "description": "Payment amount promised per product", "min_confidence": 0.7 },
        { "name": "promise_date", "type": "date", "description": "Payment date promised per product", "min_confidence": 0.7 },
        { "name": "promise_confirmed", "type": "boolean", "description": "The user confirmed the payment details." },
        { "name": "note_reason", "type": "string", "enum_values": ["refused", "hardship", "dispute", "paid", "service_error"], "description": "Reason promise was not made per product." }
      ],
      "transitions": [
        { "target_node": "products_promised_end", "description": "Some promises recorded or all products noted", "condition": { "logic": "or", "conditions": [ { "variable": "promise_ok", "operator": "equals", "operand": "true" }, { "variable": "add_note_ok", "operator": "equals", "operand": "true" } ] } },
        { "target_node": "products_stage", "description": "Other cases: keep collecting.", "condition": { "operator": "always" } }
      ]
    },
    "products_promised_end": {
      "name": "products_promised_end",
      "node_type": "end_call",
      "on_enter": { "type": "silent" },
      "disable_inactivity_monitor": true,
      "terminal": {
        "type": "function",
        "function": {
          "name": "close_call",
          "handler": "__function__:api_call",
          "parameters": {
            "type": "object",
            "properties": {
              "url": { "type": "string", "default": "https://freya-bank-mock.freyavoice.workers.dev/v1/close_call" },
              "method": { "type": "string", "default": "POST" },
              "headers": { "type": "object", "properties": { "Content-Type": { "type": "string", "default": "application/json" } } },
              "body": {
                "type": "object",
                "properties": {
                  "customer_id": { "type": "string", "default": "{{customer_id}}" },
                  "outcome": { "type": "string", "default": "promise" }
                },
                "required": ["customer_id", "outcome"]
              }
            }
          }
        }
      }
    }
  }
}
"}

